import React from 'react';
import { useParams, Link } from 'react-router-dom';
import styles from './assuntos.module.css';
import { FaEdit, FaTrashAlt, FaQuestionCircle } from 'react-icons/fa';

const GerenciamentoAssunto = () => {
  const { id } = useParams();

  return (
    <div className={styles["menu-principal-container"]}>
      {/* Sidebar Esquerdo */}
      <nav className={styles["sidebar-left"]}>
        <h1 className={styles["content-left"]}>FISIOGAME</h1>
      </nav>

      {/* Conteúdo Principal */}
      <main className={styles["main-content"]}>
        <header className={styles["content-header"]}> SISTEMA CIRCULATORIO </header>

        {/* Opções de Gerenciamento */}
        <div className={styles["assunto-actions"]}>
          <button className={styles["menu-item"]}>
            <FaEdit size={18} /> Editar Assunto
          </button>
          <button className={`${styles["menu-item"]} ${styles["delete-button"]}`}>
            <FaTrashAlt size={18} /> Excluir Assunto
          </button>
          <Link to={`/assuntos/${id}/perguntas`} className={styles["menu-item"]}>
            <FaQuestionCircle size={18} /> Visualizar Perguntas
          </Link>
        </div>
      </main>
    </div>
  );
};

export default GerenciamentoAssunto;
